--region handler
function UIWorldBossDamageRewardDialog:InitData()
    self._bossInitDojo = self._worldBossComp:GetWorldBossInitDojo()
    self._drawRewardIds = checkTable(self._bossInitDojo.hurtDrawRewardId)
    self._historyMaxHurt = checkNumber(self._bossInitDojo.historyMaxHurt)
    self._rewardsVo = CfUtils.GetCf(AutoIds.IdSetting976, "WorldBossHurtRewardVo", true)

    local worldBossInitDojo = self._overseaWorldBossComponent:GetWorldBossInitDojo()
    local hasRedPoint = worldBossInitDojo:IsCanOneKeyDraw()
    GameUtils.SetRedPointNum(Constants.RedPointConst.ABWorldBossReward, hasRedPoint and 1 or 0)
    GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.OverseaEntryWelfare)

    self:RefreshUI()
end

