function UIWorldBossDamageRewardDialog:RefreshOneKeyDraw()
    local isCanOneKeyDraw = self._bossInitDojo:IsCanOneKeyDraw()
    CfUtils.SetActive(self.FontStyleButton, isCanOneKeyDraw)
    if isCanOneKeyDraw then
        SetButtonAction(self.FontStyleButton, self.OnBtnOneKeyDrawHandler)
    end
end
