--region get / set
function UIWorldBossDamageRewardDialog:SortRewards()
    for _, reward in ipairs(self._rewardsVo) do
        ---@type WorldBossHurtRewardVo
        local rewardVo = reward
        rewardVo.isDraw = self._bossInitDojo:IsHaveDraw(rewardVo.id) and 1 or 0
    end

    table.sort(self._rewardsVo, function(a, b)
        if checkNumber(a.isDraw) <= checkNumber(b.isDraw) then
            return a.id < b.id
        end
    end)
end

function UIWorldBossDamageRewardDialog:RefreshItemByIndex(listView, index)
    local luaIndex = index + 1
    ---@type WorldBossHurtRewardVo
    local cellData = self._rewardsVo[luaIndex]
    local cell = listView:NewListViewItem("Cell")
    ---@type UIWorldBossDamageRewardCell
    local scr = CfUtils.GetLuaScr(cell, "Game.UI.FightReady.UIWorldBoss.UIWorldBossDamageBonusDialog.UIWorldBossDamageRewardCell")
    scr:Refresh(cellData)
    scr:SetDrawRewardCallback(function()
        self:InitData()
    end)
    return cell
end

function UIWorldBossDamageRewardDialog:RefreshDamageLoopView()
    if not self.DamageLoopView.IsListViewInit then
        self.DamageLoopView:InitListView(#self._rewardsVo, Bind(self, self.RefreshItemByIndex))
    else
        GameUtils.ReloadData(self.DamageLoopView, #self._rewardsVo)
    end
end
--endregion get / set

return UIWorldBossDamageRewardDialog